const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../pointer_token.cjs');
test('decode one valid reference token', () => {
  for (const [s, want] of [['',''], ['a~1b','a/b'], ['m~0n','m~n'], ['~01','~1'], ['~001','~01'], ['~1~01','/~1'], ['c%d','c%d'], ['港口','港口']]) {
    assert.equal(app.decodeToken(s), want);
  }
});
